  VALUES 
    (478::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2026-08-17T00:00:00+00:00'::TIMESTAMPTZ, 'bea959304a9a38cccff31788d3b40ec2e8cf56caea06946ef79b04f262f9da4a'::TEXT, ARRAY[563]::BIGINT[]),
    (478::BIGINT, 'Es buena profe, conversa con los alumnos y al pasar de las semanas agarra mas confianza con uno, pero si hay que notar que es vaga, si puede califica todo a la fecha limite. explica bien pero deja vacios que no sabes que existen y por eso pierdes puntos luego, la recomiendo pero no es la mejor la vd'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa']::TEXT[], '2026-07-22T00:00:00+00:00'::TIMESTAMPTZ, '34d4bba88a4502ec771f44ed6ca84a709f1eda635f10d77f163dacc67df07c37'::TEXT, ARRAY[563]::BIGINT[]),
    (478::BIGINT, 'Se caracteriza por ser muy carismática, es muy llevadera y si vas a clase y participas te transmite más confianza pero debes estudiar bastante, prepararte bien porque a veces hay aspectos en los que califica muy estricto pero si le pones, te va super bien.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases largas', 'Exámenes retadores']::TEXT[], '2026-02-20T00:00:00+00:00'::TIMESTAMPTZ, 'babc75107904f1599849e10b5b28272574dc5701794c9c35f0cc21e6a88fc45a'::TEXT, ARRAY[563]::BIGINT[]),
    (478::BIGINT, 'la peor profesora en haber tocado la superficie de la tierra. pedante, sumamente incapaz de sentir empatía y repugnante.'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-12-07T00:00:00+00:00'::TIMESTAMPTZ, 'a8c9905196602b69d00663776b81bc406c164d0ce6d570931029c3294d3c5df5'::TEXT, ARRAY[563]::BIGINT[]),
    (478::BIGINT, 'Muy buena profesora, la verdad no entiendo por que se quejan si el mismo material le ayuda durante el semestre para repasar y practicar, además de que da ejercicios de práctica moral y ayuda mucho para prepararse para los exámenes'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2025-06-26T00:00:00+00:00'::TIMESTAMPTZ, '79044d07724f3bdc7e9ca4ec25826ce64583fd26dba0d177e2f59c4edb239d8e'::TEXT, ARRAY[563]::BIGINT[]),
    (478::BIGINT, 'Si le caes bien y participas en clase te ayuda, si no, creo que no. Aparte de eso, muy buena profe, solo que no me gusta que use telegram.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa']::TEXT[], '2025-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'a14174229c7239102b6b90b31fe5a267b2b982f8a6502e46e8dfd881dddeaa74'::TEXT, ARRAY[563]::BIGINT[]),
    (478::BIGINT, 'Al principio es buena profe y explica todo bien, sin embargo con las semanas se va haciendo perezosa y deja que uno mismo aprenda en clase, no explica bien ya que para ella nosotros tenemos que entender, califica muy duro los quices y exámenes, por ella pone 0, y entre más complicado el tema más vag'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura']::TEXT[], '2025-02-13T00:00:00+00:00'::TIMESTAMPTZ, 'ed7442adbe0caaf76a9dbd96548e8d74d30bffdd47b7d2dcf78e2faf33ff1f25'::TEXT, ARRAY[605]::BIGINT[]),
    (478::BIGINT, 'No sé porque se quejan, la profe durante la clase proyecta la materia desde el iPad, además no es necesario apuntar cosas ya que ella pasa el pdf al final de la semana, hace tareas sencillas y los quizzes son ejercicios que ya entraron en las tareas, la recomiendo bastante.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2024-11-30T00:00:00+00:00'::TIMESTAMPTZ, 'fddcd9d40f4e430c75f3f27de5c5c417b553e93955c7defb4ab8005f1167cadd'::TEXT, ARRAY[563]::BIGINT[]),
    (478::BIGINT, 'La verdad no se porque dicen que es mala profe, si en lo personal este semestre fue muy buena, presenta los temas muy claros y las tareas y quices se basan en ejercicios de la Practica Semanal de Mate (Esto puede cambiar el otro semestre). Por aquello va ser la Coordinadora el otro semestre.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2024-11-30T00:00:00+00:00'::TIMESTAMPTZ, '6b8ee0716e2085b7711412e44060eb10b07733305144170cb3481cb0adb36c4f'::TEXT, ARRAY[563]::BIGINT[]),
    (478::BIGINT, 'Califica duro comparado a la materia como la da, no es buena profesora y no se practica en clases con ella nada.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2024-10-17T00:00:00+00:00'::TIMESTAMPTZ, '5fc3538bcfc3bffadd85feb0897a486d78ebae1a401ba905881d95798430099a'::TEXT, ARRAY[563]::BIGINT[]),
    (478::BIGINT, 'Muy desorganizada, no es imposible llevar el curso con ella pero si está repitiendo es una opción que podría tomar'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchos proyectos grupales']::TEXT[], '2024-09-30T00:00:00+00:00'::TIMESTAMPTZ, '13733f4a110de1022472a194eb2e83b815ad67ab90cc7356952767c18a0b382b'::TEXT, ARRAY[605]::BIGINT[]),
    (478::BIGINT, 'Califica demasiado duro a comparación de como explica. Es muy perezosa, falta mucho a clases y dura entregando evaluaciones. Es una persona odiosa, arrogante y muy altanera, agarra a los estudiantes entre ojos, especialmente a mujeres'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación']::TEXT[], '2024-09-06T00:00:00+00:00'::TIMESTAMPTZ, 'ac0f6a97cad4d51c5b39dcd70b2689b5ada01d62995c79c41c1acd91bb7040aa'::TEXT, ARRAY[605]::BIGINT[]),
    (478::BIGINT, 'Si usted está llevando Mate General por primera vez y salió con bases deficientes del colegio, no se la recomiendo, no explica de manera amplia, simplemente resuelve ejemplos con una explicación muy superficial. Eso sí, deja muy buen material de retroalimentación.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros']::TEXT[], '2024-08-11T00:00:00+00:00'::TIMESTAMPTZ, 'b5e9e309de0a18d31ca9876945d2a4a45cbd0e7da9d00b8a9847bbac4e5db161'::TEXT, ARRAY[563]::BIGINT[]),
    (478::BIGINT, 'No es una profesora que recomendaría, falta mucho a clases, hace solo un ejercicio de cada tema y más sencillo de lo que aparece en el exámen. Tiene una personalidad un poco irritable.'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes']::TEXT[], '2024-06-13T00:00:00+00:00'::TIMESTAMPTZ, '7d574ad9d32f4b8ea7bc71dd013b1f09949d20eae77cca9f1e84f4499929af87'::TEXT, ARRAY[563]::BIGINT[]),
    (478::BIGINT, 'En mate general servía, después de ahí, es una cagada matricular con esta vieja. Grosera, poco clara, aburrida y aparte arrogante. Eso sí, deja muy buen material así que si uno es disciplinado y medio autodidacta, pasa relativamente bien. Matricule como última opción.'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Aspectos de calificación claros', 'Muchos proyectos grupales']::TEXT[], '2023-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'dda6e25fde2a4b9506e4a25d1336427fe3c8e2c4a12d413229509062cb5e8dbf'::TEXT, ARRAY[605]::BIGINT[]),
    (478::BIGINT, 'no cometan el error de meter un curso con esta señora. las clases de ella son como hacer una consulta. no explica nada de teoria de la materia y sobretodo es muy maleducada y grosera. espero se retire de la enseñanza pronto.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2023-07-21T00:00:00+00:00'::TIMESTAMPTZ, '9f67e9beb052225d49bc9ef8a2bafccb53d512e87d42f34a36468e1b9b4688ec'::TEXT, ARRAY[935]::BIGINT[]),
    (478::BIGINT, 'Ella explica bien pero es muy fácil perder puntos por la cantidad de quices que pone, no son díficiles pero siempre hay que llevarlo al día.'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Muchos exámenes']::TEXT[], '2023-07-10T00:00:00+00:00'::TIMESTAMPTZ, 'e82d45f644ac5b5889cf07791a3aa018846f79522d330fe8e1167bad7647760e'::TEXT, ARRAY[563]::BIGINT[]),
    (478::BIGINT, 'Es una buena profe, usa tablet entonces las diapositivas y demas apuntes queda super claros, cuando explica se le entiende muy bien, en consulta ayuda mucho, y los quizzes son realmente faciles, califica un poco duro y le gusta ver en los examenes lo que explica en clase a detalle, en si es buena'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, '7d0d8d0b7c06a8bf3da74f4be7bfcdbf2ab1f90c5e32522bd767c4909d4f1546'::TEXT, ARRAY[563]::BIGINT[]),
    (478::BIGINT, 'Humilla a los estudiantes si uno no sabe , pasa yendo a citas por lo cual hace muchas clases virtuales en horarios no muy accesibles, lo cual afecta mucho a los estudiantes.Deja quices virtuales y también presenciales, trabaja con la tablet, las diapositivas se logran entender bien'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, '1bcd1562ba94b014c5c1a999a4cc7a0a637515ad828b077e62c7c7125ca15ae1'::TEXT, ARRAY[563]::BIGINT[]),
    (478::BIGINT, 'No es mala profesora, hace todo en tablet y proyecta, luego pasa los pdfs. Es muy muy ordenada, las calificaciones siempre al dia. Hace quiz todas las semanas, a veces con cuaderno abierto. Hace todas las clases trabajo en grupos, más que todo para resolver ejercicios.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-19T00:00:00+00:00'::TIMESTAMPTZ, '88702aa8d5b334b08bf972e102a65f9ceaae29b758703780ac07e6b0e00df6c3'::TEXT, ARRAY[563]::BIGINT[]),
    (478::BIGINT, 'No cometan el error de llevar un curso con esta señora.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2023-03-03T00:00:00+00:00'::TIMESTAMPTZ, '8d9c2b6d2f3ad620b7908d47788e0c8a56206bffcbd5813dc30a510c8c943112'::TEXT, ARRAY[563]::BIGINT[]),
    (478::BIGINT, 'Es abierta a consulta y las clases las hace en tablet y proyecta, entonces las notas son muy utiles despues para quienes no nos gusta estar copiando y poniendo atención a la vez. No es la mejor pero si es buena enseñando'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-02-22T00:00:00+00:00'::TIMESTAMPTZ, '9017c5f2cb88e6d03a706b5f8ac735349c7ca6b937b17ab60bbfd8a4b4c02634'::TEXT, ARRAY[563]::BIGINT[]),
    (478::BIGINT, 'No es una mala opción, pero no es buena ni es la mejor. Sus explicaciones son confusas y va demasiado rápido, califica como si fuera la mejor explicando pero no. Además de que es demasiado odiosa y agarra odio contra ciertos estudiantes sin razón. No volvería a llevar ningún curso con ella'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Clases largas']::TEXT[], '2022-11-26T00:00:00+00:00'::TIMESTAMPTZ, '0f62909205bcf9708bcf53b0b921bc290118ecafa6ebed8996189fa3088c2f2c'::TEXT, ARRAY[563]::BIGINT[]),
    (478::BIGINT, 'Excelente profesora, los ejercicios super claros, pide participación porque le interesa que los estudiantes aprendan, dispuesta a consultas y no dejó muchas tareas, mas que todo morales. Si le pone atención y estudia lo mínimo se pasa el curso sin complicaciones.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'f221b2db84a19ffbdbb1b8f37b6f0831712be768484516cca3c7a6105ab381b6'::TEXT, ARRAY[563]::BIGINT[]),
    (478::BIGINT, 'Es demasiado perezosa, si su clase es dos veces a la semana un dia los envía a ver los videos de otra compañera de la escuela que sí explica la materia y sus clases sincronicas son solo de resolver ejercicios y ni siquiera los resuelve de manera clara.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2022-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'f448a263ab333625935e0083c6803f026f1f05c80c6ed44bfc585ca62a5edd1f'::TEXT, ARRAY[935]::BIGINT[]),
    (478::BIGINT, 'Califica duro y a su manera con la que explica la materia. Sean puntuales con las entregas ya que no da tiempo a menos de que tenga una buena razón, explica bien en general. No da puntos extras.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2021-12-06T00:00:00+00:00'::TIMESTAMPTZ, 'eff13a3cf95b041987dda9c2876d27b95d85b1bc217bc8b8edf607683de4ff97'::TEXT, ARRAY[935]::BIGINT[]),
    (478::BIGINT, 'Explica bien, le va a ir bien en los exámenes si le entiende a ella, califica duro y jamás le va a dar un punto extra, dura en calificar las evaluaciones.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2021-12-02T00:00:00+00:00'::TIMESTAMPTZ, 'ec1be9916638a760e2cc2d50616b37a213b45f23cac4e2b91aeabd52c3879275'::TEXT, ARRAY[935]::BIGINT[]),
    (478::BIGINT, 'Explica con el detalle con el que califica, uso muchos apoyos visuales y las clases son interactivas.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2021-07-01T00:00:00+00:00'::TIMESTAMPTZ, 'f618d7a75d75b77130d869997889b03ec5a2390205412d9df6a8775cdf446846'::TEXT, ARRAY[1018]::BIGINT[]),
    (478::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-22T00:00:00+00:00'::TIMESTAMPTZ, '96b56d1566ded66284da619e1dec202b4ea5ba6bdb6f87498c7094a9db0d0e13'::TEXT, ARRAY[1018]::BIGINT[]),
    (478::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-10T00:00:00+00:00'::TIMESTAMPTZ, '0b7088e0b1e286394131505ac33beacde845733fe6887a0da94c9a1f5b91c220'::TEXT, ARRAY[563]::BIGINT[]),
    (478::BIGINT, 'En clases virtuales debe estudiar y descargar las consignas para llegar preparado a las clases.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, 'a3be9308aac876ab055059b87e4fe9355a1665d7524a0b750da5a52e13212229'::TEXT, ARRAY[1018]::BIGINT[]),
    (478::BIGINT, 'Muy buena profe de manera presencial, con la modalidad virtual se limitó mucho el aprendizaje y debe dedicar mucho tiempo a estudiar por su cuenta, sin embargo intenta dejar la materia clara para todos.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Clases largas']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, '4d2b16ca8d3d8e0a8747ec7113c27775557004dc6a40d4657372d5a1e359a23b'::TEXT, ARRAY[1018]::BIGINT[]),
    (478::BIGINT, 'En virtual la verdad es que no entendí nada, no explica bien y le presta más atención a las personas que más saben'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas']::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, 'fba62d8b1f6869259688e34fd10121fba4960e74f4c4d8d8c506d2e40508ea8e'::TEXT, ARRAY[1018]::BIGINT[]),
    (478::BIGINT, 'Las clases presenciales con ella son excelentes, lamentablemente en la modalidad virtual la clase se vuelve muy cansada y hay que dedicar muchas horas de preparación para asistir a la clase. Está dispuesta a resolver cualquier duda que tengan los estudiantes sobre su materia.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, '670fb7d4e3dea6cf3adc7da1601acfcd3e6dd5a6d67379fe35398cf156205cc0'::TEXT, ARRAY[1018]::BIGINT[]),
    (478::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas']::TEXT[], '2020-01-13T00:00:00+00:00'::TIMESTAMPTZ, '2049d78e50f4dd849e1f408264104a7ff8e0df258116f7cee4edcb0ade2a59af'::TEXT, ARRAY[1670, 1669]::BIGINT[]),
    (478::BIGINT, 'Hace muchos ejemplos por lo que a la hora de estudiar te va quedando claro. Califica muy duro, pareciera que califica para joderlo a uno, aunque diga que es una calificacion normal. Si usted no se equivoca mucho haciendo el examen, llevelo con ella sin miedo, porque por cualquier cosa mínima baja pt'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2019-12-02T00:00:00+00:00'::TIMESTAMPTZ, '17eea1d2ad1093609f260148764ce3f2087fb841420562df6de9b386e78c9a78'::TEXT, ARRAY[1670, 1669]::BIGINT[]),
    (478::BIGINT, 'La profe llega a leer diapositivas, califica los exámenes demasiado duro. Se enreda sola, muchas veces dejó ejemplos sin resolver porque no sabía como hacerlo. No pone tareas y hace muy pocos quices por lo que valen mucho porcentaje. No llevaría otro curso con ella.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2019-07-01T00:00:00+00:00'::TIMESTAMPTZ, '11e573bc26d66332f9330d80db87ab394a9a040e10ec85ff601ff9156ae816c4'::TEXT, ARRAY[605]::BIGINT[]),
    (478::BIGINT, 'Pésima profesora, lee diapositivas y le nota que no le interesa el aprendizaje de los estudiantes, no matricule con ella'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas']::TEXT[], '2019-06-28T00:00:00+00:00'::TIMESTAMPTZ, '7515184cb32f11e1358fb94454994fcac8b19e1ab1b53c23076c1db4ffbe9590'::TEXT, ARRAY[605]::BIGINT[]),
    (478::BIGINT, 'Explica muy bien, si tiene dudas le ayuda sin problema. Hace quices, no deja tareas pero si no estudia y no practica le va mal en el curso. Matricularía con ella de nuevo'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'ee567005bfe5759c6c7b907a4d6378a68f2d42e697e6f25d333bb907a07c1990'::TEXT, ARRAY[605]::BIGINT[]),
    (478::BIGINT, 'Es súper buena para explicar, merece mayor calificación de la que tiene aquí. A usted le queda claro con los ejemplos ya que hace muchísimos en clase. Eso sí, hay que estudiar mucho porque califica duro.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-19T00:00:00+00:00'::TIMESTAMPTZ, '90f1796df9e6556eed07428af3fb41af79c8cf5deb9cf023f3f549194e54646d'::TEXT, ARRAY[605]::BIGINT[]),
    (478::BIGINT, 'Excelente profesora, la verdad me asombra que tenga esta calificación en la pagina. Explica demasiado bien, pero como todo hay que poner atención. Eso sí, cabe mencionar que califica un poco fuerte los parciales, pero nada del otro mundo. Super recomendada!'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2019-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'b686afc6f1c75b3dd8ebc7bd38d27c7d76d93120f91afc121d252c065b6a01e3'::TEXT, ARRAY[605]::BIGINT[]),
    (478::BIGINT, 'Es muy buena profe, los temas quedan bien explicados y con los ejemplos uno aprende a hacer la mayoria, sin embargo la unica forma de que a uno le vaya bien es estudiando y practicando mucho'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-11T00:00:00+00:00'::TIMESTAMPTZ, '4a4089a2409bb367a317658a3f2e8aa72693012be32c802fbd1a319ada8c731a'::TEXT, ARRAY[605]::BIGINT[]),
    (478::BIGINT, 'El curso no es difícil pero esa señora califica como si fuera una diosa explicando y no es así. Utiliza presentaciones y si le pregunta por alguna demostración no sabe como responderlo porque ella no sabe mate lo que se sabe es porque se lo aprende de memoria.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-29T00:00:00+00:00'::TIMESTAMPTZ, '09cd688e531fe8f31d83de011624b81e563d75b9a3325f089b1391d6bbd991d1'::TEXT, ARRAY[923]::BIGINT[]),
    (478::BIGINT, 'Buena profe, explica demasiado bien, abre grupo de whatsapp y responde cualquier duda super claro y rapido, si hay que poner atención a los detalles que ella pide porque los exámenes califica duro si uno hace todos los pasos que ella pide'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2018-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'de8f018e7b3e52d606b90330104253286649fc22d33bfca69f0e835c9ae47cbf'::TEXT, ARRAY[923]::BIGINT[]),
    (478::BIGINT, 'Buena gente. Si usted le pide ayuda se la da. Abre grupo en WhatsApp para dudas (muy útil) y responde rápido. Explica regular, es indispensable complementar con la lectura antes de la clase para no tener problemas y seguir el hilo de la clase.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-25T00:00:00+00:00'::TIMESTAMPTZ, '154c89f8caab24e4c4c2179cd23a0f1f47ef25a5f632c4a162b1c299a8ec5682'::TEXT, ARRAY[605]::BIGINT[]),
    (478::BIGINT, 'Fatal simplemente no matricule con esta señora, recomendada JAMAS no se embarque'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'c66fcdd78f8d9fd2104190b34f8048597b9d0bd54ece80b170ff14f6b7622cae'::TEXT, ARRAY[634]::BIGINT[]),
    (478::BIGINT, 'Hay algunos detalles que ella siempre pide en los exámenes. Explica bien. Presentaciones claras y a veces manda vídeos hechos por ella.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-01T00:00:00+00:00'::TIMESTAMPTZ, '030c901bcb2ef6a6f31b1cd86210310811a0a77a66fc6d75f549c37d40fda17d'::TEXT, ARRAY[923]::BIGINT[]),
    (478::BIGINT, 'Excelente profesora. Es súper abierta para todo tipo de preguntas, abre grupo en WA para aclarar dudas y provee muchos exámenes viejos para practicar. Cuando explica una se siente iluminada.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-01-29T00:00:00+00:00'::TIMESTAMPTZ, '63a49cfc014e96cd58b347072d0d3bb1782d26b363a1fea70985d84a58136b8d'::TEXT, ARRAY[923]::BIGINT[]),
    (478::BIGINT, 'Buena profesora, da la clase con presentaciones, por lo que no es cualquiera al que le sirve, ya que se requiere que el estudiante repase antes y despues lo visto en clase, pero si se le pregunta explica muy claro'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-01-25T00:00:00+00:00'::TIMESTAMPTZ, 'af54de3aaa1135e2b26878307e0c630843d414f9bda405f4a96f0cf90f792158'::TEXT, ARRAY[923]::BIGINT[]),
    (478::BIGINT, 'Excelente profe! Califica muy bien, explica muy muy bien, súper ordenada. Aclara muchísimo las dudas. Es increíble.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-25T00:00:00+00:00'::TIMESTAMPTZ, '950d5d2c71da6397b10f79ed01d12dfe95ba3c84b43b3ecc32fbcf6c6c98aab3'::TEXT, ARRAY[923]::BIGINT[]),
    (478::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2018-01-13T00:00:00+00:00'::TIMESTAMPTZ, 'c31618538e7225a6f9ca52efaca19c99686135444367c85af847b810eb543e87'::TEXT, ARRAY[1670, 1669]::BIGINT[]),
    (478::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clase fácil', 'Exámenes retadores']::TEXT[], '2017-12-06T00:00:00+00:00'::TIMESTAMPTZ, 'de9db233ed867d7df15a6d342e50cf814f65020e5fd00c050c7309204855f121'::TEXT, ARRAY[605]::BIGINT[]),
    (478::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2017-11-25T00:00:00+00:00'::TIMESTAMPTZ, '1e7302e64d6b52d1e674eccae153651cabebd24659772cafa066f2a1449545d1'::TEXT, ARRAY[634]::BIGINT[]),
    (478::BIGINT, 'Es buena profe, pero no tiene la experiencia necesaria para ese curso, a pesar de sus materiales no explica muy bien, sus clases son aburridas.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-10-31T00:00:00+00:00'::TIMESTAMPTZ, 'a65a0ddf0f7e49909f032bda55ae1c6afc8987766a83f29d81f29e091c6bb769'::TEXT, ARRAY[923]::BIGINT[]),
    (478::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Brinda apoyo']::TEXT[], '2017-10-13T00:00:00+00:00'::TIMESTAMPTZ, '8b0e6903b5b2c84c5590ba532a98b228a6301ca9427e04251d4fc7863711a882'::TEXT, ARRAY[634]::BIGINT[]),
    (478::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-09-12T00:00:00+00:00'::TIMESTAMPTZ, '9f9705660a99197815dff3744eb1a52a1c4b0ff325dfc9aa9c1ba3bd89bd2013'::TEXT, ARRAY[923]::BIGINT[]),
    (478::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2017-06-28T00:00:00+00:00'::TIMESTAMPTZ, '5fda8919bd6769e6492233dae2426efccb2155695697181c3d8f0ad60b4a8337'::TEXT, ARRAY[1641, 1642]::BIGINT[]),
    (478::BIGINT, 'La mejor de lo mejor. Si usted lleva hechas las presentaciones a clase llega solo a evacuar dudas y a los exámenes llega demasiado bien. Recomendada al 100%'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2017-06-14T00:00:00+00:00'::TIMESTAMPTZ, '391a4f652f13bef4693306b6e8c90457fa4eab6d01eff2060e28c2a3c916aabe'::TEXT, ARRAY[935]::BIGINT[]),
    (478::BIGINT, 'Excelente profe! No es imposible sacarse 100 en los quices con el ella si uno le pone de verdad y sigue instrucciones! Un poco de disciplina y el curso se vuelve fácil!'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Brinda apoyo']::TEXT[], '2017-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'c513a1c990f912cf33ec4ce3116b776d80a7125d844cb5417f11f43b49093561'::TEXT, ARRAY[923]::BIGINT[]),
    (478::BIGINT, 'Explica bien, califica rudillo, nada fuera de lo normal, es una buena profe'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-31T00:00:00+00:00'::TIMESTAMPTZ, 'ab8578332d3db751aaae80ca936bedcb69449010032ea0f740d39646c8634b69'::TEXT, ARRAY[634]::BIGINT[]),
    (478::BIGINT, 'Califica justo como enseña, hace bastantes ejercicios y de alto nivel, uno va súper preparado a los exámenes, excelente profe.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-26T00:00:00+00:00'::TIMESTAMPTZ, 'ee9182d2047a17a21c184e3a12dfed6161032bb7800980010b470cc13f57f484'::TEXT, ARRAY[605]::BIGINT[]),
    (478::BIGINT, 'Todo lo que explica se entiende, si usted está en un puro chingue pues no va a entender... y sí, califica duro'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-01-21T00:00:00+00:00'::TIMESTAMPTZ, '6e7903e106bd9dfdafb6f4199c345ecab17b714c1b7a0245a282ccf0a327f32c'::TEXT, ARRAY[1641, 1642]::BIGINT[]),
    (478::BIGINT, 'Super ruda revisando. Si lo tienes bueno pero no es como ella te enseño. Esta malo. Explica muy bien. Pero no es justa'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria']::TEXT[], '2017-01-18T00:00:00+00:00'::TIMESTAMPTZ, '5ba2b035b63a113c5b7812374c3e9d0d89ebe0dc4353279ec811380c38671437'::TEXT, ARRAY[1670, 1669]::BIGINT[]),
    (478::BIGINT, 'Explica bien pero califica muy duro lo cual hace un poco díficil aprobar, los quices no son díficiles pero si hay que hacer todo como ella lo ha hecho en la pizarra y hace como 6 a lo largo del semestre.'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Clases excelentes']::TEXT[], '2016-12-15T00:00:00+00:00'::TIMESTAMPTZ, '1acabb9c9260f858beec5e7ce6877c1da6dd8ae06f927d50b23e63dec4a824f3'::TEXT, ARRAY[634]::BIGINT[]),
    (478::BIGINT, 'Pésima profe, no sabe tratar al estudiante, califica duro y en mi opinión no es muy buena explicando'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-12-09T00:00:00+00:00'::TIMESTAMPTZ, '12e529f232275d907c387a0f09e79c02f0532a1dacbc8b69a1dfd4ebaf172e8e'::TEXT, ARRAY[923]::BIGINT[]),
    (478::BIGINT, 'Dificil, es una persona que le agarra odio a las mujeres.'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-12-07T00:00:00+00:00'::TIMESTAMPTZ, 'ab218776645aee8467867bdceee88aae67f624ed3a15b9c089ce84e06cf62527'::TEXT, ARRAY[1018]::BIGINT[]),
    (478::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-12-07T00:00:00+00:00'::TIMESTAMPTZ, 'ef03aabb06d1085f75137cb00f4ef41520ea8c2e00dea4781d0b0bc9b881f6c4'::TEXT, ARRAY[1670, 1669]::BIGINT[]),
    (478::BIGINT, 'Excelente profe.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-12-02T00:00:00+00:00'::TIMESTAMPTZ, 'ccace918aa29c0aa25c435c03d1bd45b8427435ba8c9063b6befe1477a17073e'::TEXT, ARRAY[923]::BIGINT[]),
    (478::BIGINT, 'Es buena gente, hace quices sacados del folleto y no son difíciles,eso ayuda a subir el promedio y los ejemplos que da son similares a los del examen, califica un toque duro pero es consciente si uno hace algo bien Dele sin miedo!'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-12-01T00:00:00+00:00'::TIMESTAMPTZ, '6168bff04e94845e4891d1880866facba9c6d2ad931f458be3badf4f5c8f6d91'::TEXT, ARRAY[923]::BIGINT[]),
    (478::BIGINT, 'Es muy tuanis. Quiere intimidar pero no puede. Califica normal y explica demasiado bien, por eso su forma de calificar me parece aceptable. Las presentaciones pegan salvadones. Quices fáciles.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-25T00:00:00+00:00'::TIMESTAMPTZ, '41001c39a6394ea2b0cab293df0c8505a384ddf2ce550df923ed05d2f74bbbdb'::TEXT, ARRAY[923]::BIGINT[]),
    (478::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-24T00:00:00+00:00'::TIMESTAMPTZ, '7ea89a16eca20d3d29c06bc56fa21932d9b4a2143916327c62d5bee062c980a6'::TEXT, ARRAY[923]::BIGINT[]),
    (478::BIGINT, 'Califica sin piedad, loz quizes no son faciles pero tampoco imposibles, explica regular pero si le pone mucho y es ordenado en los exámenes fijo fijo pasa'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2016-06-28T00:00:00+00:00'::TIMESTAMPTZ, '798062050319a4d9538431cf6e32161a2702bb1011d4a4c5c79740607e381f49'::TEXT, ARRAY[634]::BIGINT[]),
    (478::BIGINT, 'Buena profesora.La verdad es buena siempre y cuando uno tenga un interés adecuado de la materia y preste atención en clase.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-24T00:00:00+00:00'::TIMESTAMPTZ, '4340e97448fded8c508a5102f1854b72188708fa6478c3c3e18a4bf1b139f4f3'::TEXT, ARRAY[1018]::BIGINT[]),
    (478::BIGINT, 'Explica bien, hace presentaciones en power point y las sube al tecdigital, muchos ejemplos, sube examenes resueltos. No me agrado que muchas veces pone a hacer ejemplos a los estudiantes cuando solo ha explicado teoría, igual al final ella lo resuelve. CALIFICA A MATAR DURISIMO DURISIMO'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-23T00:00:00+00:00'::TIMESTAMPTZ, '6f4e9fd6f0c82492524e135c3c03020daec3b3a5416ff06602360ca07ea832b2'::TEXT, ARRAY[605, 634]::BIGINT[]),
    (478::BIGINT, 'Lleve discreta por primera vez con ella, la verdad me gustó su clase. Deja bastantes ejercicios extra, explica bastante bien y atiende las dudas. Califica medio duro.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-11T00:00:00+00:00'::TIMESTAMPTZ, '9d387685f973318d3cf7173d3037a23eea4e8c252f28636438d887bc8841213b'::TEXT, ARRAY[1018]::BIGINT[]),
    (478::BIGINT, 'Califica muy duro, pero explica bien.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-08T00:00:00+00:00'::TIMESTAMPTZ, 'cbc38cb0fac71ca698b5b0975c472598d9ac6cd5132ed6b172905c0d6a7adc25'::TEXT, ARRAY[1641, 1642]::BIGINT[]),
    (478::BIGINT, 'Buena a veces pero explica de una forma un poco confusa'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-05-09T00:00:00+00:00'::TIMESTAMPTZ, 'ed64219eb98e8da150e412b10e09a538459a6d30137ea91797108bfd221dc79d'::TEXT, ARRAY[1018]::BIGINT[]),
    (478::BIGINT, 'Si lleva el curso por segunda vez puede que pase. No la remiendo si lo lleva por primera vez por que va muy rápido.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2016-02-02T00:00:00+00:00'::TIMESTAMPTZ, '8138627ad32da656fa2fdf163d4020ffdd03883689ed13fb24f052e06fdd891c'::TEXT, ARRAY[1018]::BIGINT[]),
    (478::BIGINT, 'Como profe es muy buena, califica justo, es responsable y bien organizada. Siempre está pendiente de los correos por cualquier consulta. Genera un clima de confianza en el aula. Para pasar solamente se necesita ser puntual con todo y estudiar bastante.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-20T00:00:00+00:00'::TIMESTAMPTZ, '71f02653ca9735e9ec081dd4db5d3fac11bd61a7d93e94812fd67a5d2908e87f'::TEXT, ARRAY[1018]::BIGINT[]),
    (478::BIGINT, 'Muy buena profe, si es estricta para calificar pero explica muy bien! Excelente Profesora'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-12-01T00:00:00+00:00'::TIMESTAMPTZ, '72bee9c57fd8a44ee5ff7fa3ae08e68dab426da1bb3e51571e4b6e133aeb9854'::TEXT, ARRAY[1018]::BIGINT[]),
    (478::BIGINT, 'Para mate diacreta la recomiendo si uno está repitiendo el curso porque si lo lleva por primera vez con ella difícilmente va a entender ya que tiene la costumbre de enviar las presentaciones antes para que uno "llegue estudiado a la clase". Para calificar es muy ruda y se fija en muchos detalles'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-19T00:00:00+00:00'::TIMESTAMPTZ, 'c5f964897aea9db9a2a0154a1230669c68faad2c1e777d518dc1d824fa5bb272'::TEXT, ARRAY[1018]::BIGINT[]),
    (478::BIGINT, 'Explica muy completo y es muy anuente a responder consultas.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-07T00:00:00+00:00'::TIMESTAMPTZ, '792a0d54d422f335715193e052c1f5425a2b892f5dd81e9c356de18f4ffaf1a1'::TEXT, ARRAY[1864]::BIGINT[]),
    (478::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-04T00:00:00+00:00'::TIMESTAMPTZ, '56121c5d0e03a3243422d185d8805d8385b44ace1a5d4d77ad89b1e73d00befd'::TEXT, ARRAY[1018]::BIGINT[]),
    (478::BIGINT, 'No se le entiende nada!! Explica mate con diapositivas :\'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('20','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-04T00:00:00+00:00'::TIMESTAMPTZ, 'b7ceac3c8d3ca16993aee94f83787ae6e2a2f218d41a45f6d48e23fb2c065b7a'::TEXT, ARRAY[923]::BIGINT[]),
    (478::BIGINT, 'Califica muy duro! Enseña muy bien, pero calificando no tiene misericordia.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'c4342585f89311f1f419105f3d4d4630ff12c8771af3dbb9d8b26cb38baa1e40'::TEXT, ARRAY[634]::BIGINT[]),
    (478::BIGINT, 'Mucho recurso visual, tiene la buena costumbre de dar el material de la clase antes para al menos leerla deja trabajos apropiados en lugar de quices y ademas siempre evalua con un nivel similar a la clase, no se vuela como en otros cursos. contesta preguntas en clase y correo siempre con bna actitud'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-23T00:00:00+00:00'::TIMESTAMPTZ, '7f902cebb3b872645a39bbe11e735ecabe1d19aa5408a1c8ccbf6ab4ec673753'::TEXT, ARRAY[1864]::BIGINT[]),
    (478::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('40','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-20T00:00:00+00:00'::TIMESTAMPTZ, '03d9414dc985b399404af0227bd65faba2e0ead27a87ad2b6ea985c6c3f084c5'::TEXT, ARRAY[563]::BIGINT[]),
    (478::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-14T00:00:00+00:00'::TIMESTAMPTZ, '2418a0c2a297312c4177e10810c2443683cddde9e1ad59dc3799e170f6d04a3c'::TEXT, ARRAY[563]::BIGINT[]),
    (478::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-13T00:00:00+00:00'::TIMESTAMPTZ, '4a69831a1a0c3b87c9241e868310228d888700ec6ffe6e22091489661a5a4d10'::TEXT, ARRAY[605, 1864]::BIGINT[]),
    (478::BIGINT, 'cuesta entenderle, califica muy duro'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-05T00:00:00+00:00'::TIMESTAMPTZ, 'deb466c54951accf26c8321d5074efa1c4e3f027b50cb31d0456b6f352926cd4'::TEXT, ARRAY[1018]::BIGINT[]),
    (478::BIGINT, 'Excelente para los que somos visuales, en clase se hace mucha practica'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-29T00:00:00+00:00'::TIMESTAMPTZ, 'a2c44e1acef2156eadb94dc2a611e0993887b3e8a882cf187d7f76f69b8e9290'::TEXT, ARRAY[1018]::BIGINT[]),
    (478::BIGINT, 'Le pesa la mano, solo presentaciones y pocos ejercicios'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-03-20T00:00:00+00:00'::TIMESTAMPTZ, '8e6671f645451cbef529840f5df5181e1d297ba4d2f57b0f9b2a809c757111b5'::TEXT, ARRAY[923]::BIGINT[]),
    (478::BIGINT, 'No es clara en absoluto al explicar, los ejemplos cuesta entenderlos porque los hace demasiado rápido y no es muy atenta.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('30','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-02-25T00:00:00+00:00'::TIMESTAMPTZ, '52bafccd93654396cf2f3ad7285736879025b405fa5e215af0356e6fb5eaea67'::TEXT, ARRAY[1018]::BIGINT[]),
    (478::BIGINT, 'Lo llevé con ella en verano, apesar de lo apresurado que ésta modalidad (sólo como 5 días para ver la materia del 3er parcial) conlleva las clases fueron bastante claras y entretenidas, bastantes ejemplos tanto de folletos como de exámenes. Eso sí es estricta a la hora de calificar o redonder'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-02-05T00:00:00+00:00'::TIMESTAMPTZ, 'af5b50e1552cdf4fcb97a1469d59536addd1f5ad6f08b604c7ea3b606c7ace83'::TEXT, ARRAY[923]::BIGINT[]),
    (478::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-27T00:00:00+00:00'::TIMESTAMPTZ, '64697524017d14391da43afe8d18698c89269685f20e4466403c2be8689c8e4f'::TEXT, ARRAY[563]::BIGINT[]),
    (478::BIGINT, 'Es una excelente profesora, explica super bien, es muy organizada con sus clases y da material de apoyo para que uno practique y entienda la materia como diapositivas, le gusta hacer mucha practica en clase. Es buena gente.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-13T00:00:00+00:00'::TIMESTAMPTZ, '87e50ca4fcf74bb41d24fcc05875ed5f8793886bf29362cbfd399145f97867f6'::TEXT, ARRAY[563]::BIGINT[]),
    (478::BIGINT, 'Exelente Profe, el orden en su materia, es primordial en una clase, ella lo tiene, las presentaciones que tiene y utiliza son de apoyo, pero fundamentales, ella resuelve y explica y después tu,con solo hacer las presentaciones y entenderle a ella es necesario para aprobar el curso,resuelve dudas.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-03T00:00:00+00:00'::TIMESTAMPTZ, '6d058ce69c9d54a23023c29d9d0736155a71613bd107af60fcffc25b58da7722'::TEXT, ARRAY[1018]::BIGINT[]),
    (478::BIGINT, 'Para mate general no la recomiendo'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-30T00:00:00+00:00'::TIMESTAMPTZ, '30e27f47110ff65d4c4181ec92e7b1d9a2fe53e22c713d939733a187279f5097'::TEXT, ARRAY[605]::BIGINT[]),
    (478::BIGINT, 'Explica demasiado bien.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '75e57b7e38083c23d63d98fb85929226f543841b7922d84c62bbc36f779c15be'::TEXT, ARRAY[1641, 1642]::BIGINT[]),
    (478::BIGINT, 'Profe demasiado buena, califica duro pero es por que es muy buena a la hora de explicar, sube diapositivas con la materia del curso y enseña diferentes maneras de hacer los ejercicios se le entiende demasiado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-17T00:00:00+00:00'::TIMESTAMPTZ, 'b60e3479184c1005b2e08f640c673cc9fed1358e579c82720cbd569d4a561bd0'::TEXT, ARRAY[563]::BIGINT[]),
    (478::BIGINT, 'Explica con facilidad'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-16T00:00:00+00:00'::TIMESTAMPTZ, 'a3e563a84f76afd7ccff6201e754959b4b34248067e5366e7056e59d94029d59'::TEXT, ARRAY[605]::BIGINT[]),
    (478::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('5','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'a6639728c37c6bc141467897fc0be7f6c2d4fce1800d0e0f8e0df8354c8be38c'::TEXT, ARRAY[1018]::BIGINT[]),
    (478::BIGINT, 'Para mate general no es recomendable, cursos mas avanzados si.'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('40','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'a4e5ccdb7dd2384075b3504ccf11804ff8e35c2d559b923fbc86d2803afcc69a'::TEXT, ARRAY[563]::BIGINT[]),
    (478::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '20db540d19d2e331a23e0a04962e4608aeb1ecf24be2981ffdc0eb588d1886f4'::TEXT, ARRAY[563]::BIGINT[]),
    (478::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '68209a70c1460a7b532d253c2182fedca087171bb115b145ea046a948e11de80'::TEXT, ARRAY[923]::BIGINT[]),
    (478::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'cc0ec8e2182c1c2a893d791849e7d3c220cad021226a562e5603f6cf6c841dee'::TEXT, ARRAY[923]::BIGINT[]),
    (478::BIGINT, 'Muy buena profe, muy buenos métodos de enseñanza.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'df3d8511544b032d77ea26479441ab892a21806f6dcfa1db706a532b2ff5fb03'::TEXT, ARRAY[1641, 1642]::BIGINT[]),
    (478::BIGINT, 'No es muy buena explicando pero los quices son super faciles entonces se obtiene esa nota facil, ademas si da alguillo de materia y bastantes ejemplos... tambien da examenes resueltos para estudiar!'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-14T00:00:00+00:00'::TIMESTAMPTZ, '2b3a5f20c1b426d7e44391d0108ce7bced2b7691be023479040527e5619e66fa'::TEXT, ARRAY[563]::BIGINT[]),
    (478::BIGINT, 'Los quices son mucho con lo que ella da en clase, se ayuda porque se gana bien el porcentaje de quices. Se la juega. Tampoco califica muy rudo.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-14T00:00:00+00:00'::TIMESTAMPTZ, '9b7cd2b624e658d3e388a9a0427469a2b1c6bd75d868e36aa001cd9b364c0d96'::TEXT, ARRAY[563]::BIGINT[]),
    (478::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-14T00:00:00+00:00'::TIMESTAMPTZ, '37a5ba36f776cbc7f19bd6da4adbd32bfbab4afa48b993e80b57477e214dd9ff'::TEXT, ARRAY[923]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
